window.kbPageData["views/entry/k-52ce365008e73bc8"] = {"key":"entry/k-52ce365008e73bc8","state":{"route":"entry/k-52ce365008e73bc8"},"node":{"id":"k-52ce365008e73bc8","mode":"k","title":"更大力度保障和改善民生","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment","modern"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["公共管理","社会治理"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"更好满足人民群众精神文化需求。以社会主义核心价值观①引领文化建设。发展哲学社\n会科学事业，推动新闻出版、广播影视、文学艺术等领域精品创作。加强网络内容建设和管\n理，深化网络综合治理，推进未成年人网络保护。实施公共文化服务提质增效行动，做好公\n共图书馆、博物馆、文化馆等惠民开放，完善全民阅读推广服务体…","sources":[{"id":"87c9e6cc976223bc","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"更好满足人民群众精神文化需求。以社会主义核心价值观①引领文化建设。发展哲学社\n会科学事业，推动新闻出版、广播影视、文学艺术等领域精品创作。加强网络内容建设和管\n理，深化网络综合治理，推进未成年人网络保护。实施公共文化服务提质增效行动，做好公\n共图书馆、博物馆、文化馆等惠民开放，完善全民阅读推广服务体系②，广泛开展群众性文\n化活动，繁荣互联网条件下新大众文艺。发展档案事业。深入实施中华优秀传统文化传承\n发展工程③，完成第四次全国文物普查④，加强文化遗产系统性保护、监管和合理利用。高质\n量发展文化旅游业，丰富文旅体商等融合业态。鼓励更多文化企业和优秀文化产品走向世界，\n增强主流媒体国际传播能力。做好 2026 年亚运会⑤备战参赛工作。加快重塑足球青训体系。\n积极发展赛事经济、冰雪经济、户外运动，建好用好群众身边的运动场地设施，培育更多特\n色群众体育赛事活动。","source":{"doc":"6cbfb01fe723bba64b75","first":43,"last":43,"page":43,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"7ba474934bd98273","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"加强社会保障和服务。城乡居民基础养老金月最低标准再提高 20 元①。完善并落实基\n本养老保险全国统筹制度，扩大失业、工伤保险覆盖面，稳妥有序推进职业伤害保障试点扩\n围，健全社保关系转移接续政策。深入实施积极应对人口老龄化国家战略②，扩大普惠养老\n服务供给，积极发展农村养老服务，实施中度以上失能老年人养老服务消费补贴项目。积极\n开发老年人力资源，制定推进银发经济③高质量发展的措施，完善老年用品产品、养老金融、\n旅居养老等支持政策。实施康复护理扩容提升工程。推行长期护理保险制度。做好独居老人、\n失能失智等困难群体的关爱帮扶。倡导积极婚育观。加强初婚初育家庭住房保障，支持多\n子女家庭改善性住房需求。完善生育保险制度和生育休假制度。深入开展托育服务补助示范\n试点，发展普惠托育和托幼一体化服务。加强残疾预防、康复和托养照护服务，推进养老助\n残资源统筹利用。做好困境儿童关爱服务，保障妇女儿童合法权益。加强军人军属、退役军\n人和其他优抚对象服务保障。建立健全基本殡葬服务制度。分层分类做好社会救助工作，兜\n住兜牢民生底线。","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":43,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"d6508f6770645279","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"强化基本医疗卫生服务。实施健康优先发展战略①，健全健康促进政策制度体系，提升\n爱国卫生运动②成效，强化公共卫生能力。健全医疗、医保、医药协同发展和治理机制，深\n化以公益性为导向的公立医院改革，加强县区、基层医疗机构运行保障。强化薄弱专科建设，\n全方位提升急诊急救、血液保障和应急能力。优化医疗机构功能定位和布局，加强基层用药\n衔接，做实家庭医生签约服务，促进分级诊疗。推进中医药传承创新，促进中西医结合。居\n民医保人均财政补助标准提高 24 元③。健全多层次医疗保障体系，稳步推动基本医疗保险\n省级统筹，优化医药集中采购和价格治理，深化医保支付方式改革，完善结余资金使用政策。\n坚决打击欺诈骗保。加快发展商业健康保险，推动创新药和医疗器械高质量发展，更好满足\n人民群众多元化就医用药需求。","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"51149344a9fef782","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"推动教育公平与质量提升。实施新时代立德树人工程①，促进思政课堂和社会课堂有效\n融合。适应学龄人口结构变化，推进教育资源布局结构调整。推动基础教育扩优提质，统筹\n义务教育优质均衡发展、学前教育优质普惠发展，完善免费学前教育政策，增加普通高中\n学位供给。持续扩大优质本科教育招生规模。提升职业学校办学能力，建设特色鲜明高职院\n校。办好特殊教育、专门教育，提升终身学习公共服务水平，引导规范民办教育发展。建设\n高素质专业化教师队伍②，加强师德师风建设，强化教师待遇保障。加强体育、美育、劳动\n教育和心理健康教育③，健全学校家庭社会协同育人机制，促进学生身心健康、全面发展。","source":{"doc":"6cbfb01fe723bba64b75","first":41,"last":41,"page":41,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"883805ea74f5491f","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"（八）更大力度保障和改善民生。坚持民生为大，加强普惠性、基础性、兜底性民生\n建设①，努力为人民群众多办实事。\n促进高质量充分就业②。加大各类政策对就业的支持力度，构建就业友好型发展方式③。\n延续实施稳岗返还、社保补贴、专项贷款等阶段性措施，进一步增加以工代赈投资规模。实\n施稳岗扩容提质行动，支持劳动密集型行业企业④稳定岗位，围绕发展新兴产业、未来产业\n培育新职业新岗位，增强服务业带动就业能力。制定高校毕业生等青年就业支持政策，强化\n农民工稳岗帮扶，做好退役军人安置和就业服务，加强困难人员就业援助，出台支持灵活就\n业人员、新就业形态人员参加职工保险的政策。发挥创业担保贷款贴息等政策作用，加强创\n业支持引导。完善适应人工智能技术发展促进就业创业的措施。全面落实农民工工资支付\n保障制度，加强就业歧视治理⑤，坚决维护劳动者合法权益。持续开展大规模职业技能提升\n培训，让更多劳动者拥有一技之长，更好就业增收。","source":{"doc":"6cbfb01fe723bba64b75","first":39,"last":39,"page":39,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-52ce365008e73bc8":[]}};
